#include "/lib/lighting.glsl"
uniform sampler2D texture;
uniform sampler2D colortex4;
uniform sampler2D depthtex1;
uniform mat4 gbufferModelView;
varying vec2 vUV;
varying vec2 vLM;
varying vec4 vColour;
varying vec3 vPlayer;
varying vec3 vNormal;
varying float vMaterial;
vec3 traceScene(vec3 origin, vec3 ray, vec3 fallback) {
    float previousDifference = -1.0;
    vec3 previousPoint = origin;
    for (int i = 1; i <= 48; ++i) {
        float f = float(i) / 48.0;
        float travel = 0.14 + f * f * 144.0;
        vec3 point = origin + ray * travel;
        vec4 clip = gbufferProjection * vec4(point, 1.0);
        if (clip.w < 0.05) break;
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        if (any(lessThan(uv, vec2(0.005))) || any(greaterThan(uv, vec2(0.995)))) break;
        float depth = texture2D(depthtex1, uv).r;
        float difference = depth < 0.99999 ? viewPosition(uv, depth).z - point.z : -1000.0;
        if (difference >= 0.0 && previousDifference < 0.0) {
            vec3 low = previousPoint, high = point;
            for (int j = 0; j < 5; ++j) {
                vec3 mid = (low + high) * 0.5;
                vec4 c = gbufferProjection * vec4(mid, 1.0);
                vec2 u = c.xy / c.w * 0.5 + 0.5;
                float d = texture2D(depthtex1, u).r;
                if (d < 0.99999 && viewPosition(u, d).z - mid.z >= 0.0) high = mid; else low = mid;
            }
            vec4 c = gbufferProjection * vec4(high, 1.0);
            vec2 hit = c.xy / c.w * 0.5 + 0.5;
            float sceneZ = viewPosition(hit, texture2D(depthtex1, hit).r).z;
            if (abs(sceneZ - high.z) < 0.7 + travel * 0.025) {
                float edge = smoothstep(0.005, 0.08, min(min(hit.x, hit.y), min(1.0 - hit.x, 1.0 - hit.y)));
                return mix(fallback, texture2D(colortex4, hit).rgb, edge);
            }
        }
        previousPoint = point; previousDifference = difference;
    }
    return fallback;
}
void main() {
    vec4 texel = texture2D(texture, vUV) * vColour;
    if (texel.a < 0.01) discard;
    vec3 n = normalize(vNormal);
    if (abs(vMaterial - 1001.0) > 0.5) {
        vec3 colour = lightSurface(toLinear(texel.rgb), n, vPlayer, vLM, 1.0, 1.0);
        gl_FragData[0] = vec4(colour, clamp(texel.a, 0.0, 1.0));
        return;
    }
    vec3 absolutePosition = vPlayer + cameraPosition;
    float t = frameTimeCounter;
    vec2 p = absolutePosition.xz;
    vec2 slopes = vec2(cos(dot(p, vec2(0.70, 0.40)) + t * 0.8), cos(dot(p, vec2(-0.45, 0.80)) - t * 0.65));
    n = normalize(n + vec3(slopes.x, 0.0, slopes.y) * WATER_WAVES);
    vec3 view = (gbufferModelView * vec4(vPlayer, 1.0)).xyz;
    vec3 eye = normalize(-view), normalView = normalize(mat3(gbufferModelView) * n);
    if (dot(normalView, eye) < 0.0) { normalView = -normalView; n = -n; }
    vec3 reflectedView = reflect(-eye, normalView);
    vec3 reflectedWorld = worldDirection(reflectedView);
    vec3 reflection = traceScene(view + normalView * 0.12, reflectedView, skyRadiance(reflectedWorld));
    vec2 screen = gl_FragCoord.xy / vec2(viewWidth, viewHeight);
    vec2 refracted = clamp(screen + normalView.xy * 0.012, vec2(0.002), vec2(0.998));
    float bedDepth = texture2D(depthtex1, refracted).r;
    vec3 bed = viewPosition(refracted, bedDepth);
    if (bedDepth < gl_FragCoord.z) { refracted = screen; bed = viewPosition(screen, texture2D(depthtex1, screen).r); }
    float thickness = clamp(length(bed - view), 0.0, 24.0);
    vec3 transmitted = texture2D(colortex4, refracted).rgb;
    vec3 transmission = exp(-vec3(0.20, 0.065, 0.035) * thickness);
    vec3 waterTint = vec3(0.025, 0.16, 0.19) * mix(0.12, 0.8, daylight());
    transmitted = transmitted * transmission + waterTint * (1.0 - transmission);
    float fresnel = 0.025 + 0.975 * pow(1.0 - max(dot(normalView, eye), 0.0), 5.0);
    vec3 colour = mix(transmitted, reflection, fresnel);
    vec3 halfVector = normalize(normalize(shadowLightPosition) + eye);
    float sparkle = pow(max(dot(normalView, halfVector), 0.0), 220.0);
    colour += directColour() * sparkle * daylight() * 8.0 * shadowVisibility(vPlayer, n, worldDirection(shadowLightPosition));
    // Refraction already contains the bed: opaque output avoids applying alpha twice.
    gl_FragData[0] = vec4(colour, 1.0);
}

#version 120
attribute vec4 mc_Entity;
varying float vMaterial;
#include "/lib/geometry_vertex.glsl"
void main() { mhVertex(); vMaterial = mc_Entity.x; }

#ifndef MH_COMMON
#define MH_COMMON
// Original ModHorizon renderer. Look controls; buffer contracts are not look controls.
#define SUN_INTENSITY 3.2 // [2.0 2.6 3.2 3.8]
#define AMBIENT_STRENGTH 0.32 // [0.20 0.26 0.32 0.42]
#define FOG_DENSITY 0.0035 // [0.0015 0.0025 0.0035 0.0050]
#define WATER_WAVES 0.045 // [0.015 0.030 0.045 0.060]
#define BLOOM_STRENGTH 0.10 // [0.0 0.05 0.10 0.15]
#define EXPOSURE 1.05 // [0.85 1.0 1.05 1.15]
#define SURFACE_RELIEF 0.065 // [0.0 0.035 0.065 0.09]
#define MATERIAL_HIGHLIGHTS 1.0 // [0.0 0.5 1.0 1.5]
uniform mat4 gbufferModelViewInverse;
uniform mat4 gbufferProjection;
uniform mat4 gbufferProjectionInverse;
uniform vec3 sunPosition;
uniform vec3 shadowLightPosition;
uniform vec3 cameraPosition;
uniform float frameTimeCounter;
uniform float rainStrength;
uniform float viewWidth;
uniform float viewHeight;
uniform float far;
uniform int isEyeInWater;
const float MH_PI = 3.14159265;
vec3 toLinear(vec3 c) { return pow(max(c, vec3(0.0)), vec3(2.2)); }
vec3 worldDirection(vec3 v) { return normalize(mat3(gbufferModelViewInverse) * v); }
vec3 sunWorld() { return worldDirection(sunPosition); }
float daylight() { return smoothstep(-0.12, 0.12, sunWorld().y); }
float goldenHour() { return (1.0 - smoothstep(0.08, 0.55, abs(sunWorld().y))) * daylight(); }
vec3 directColour() { return mix(vec3(1.0, 0.96, 0.85), vec3(1.0, 0.54, 0.24), goldenHour() * 0.82); }
float hash21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise2(vec2 p) {
    vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + vec2(1.0, 0.0)), f.x),
               mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0)), f.x), f.y);
}
float cloudNoise(vec2 p) { return noise2(p) * 0.57 + noise2(p * 2.07 + 17.0) * 0.28 + noise2(p * 4.13) * 0.15; }
vec3 skyRadiance(vec3 direction) {
    vec3 rd = normalize(direction), sun = sunWorld();
    float day = daylight(), gold = goldenHour();
    float elevation = clamp(rd.y, 0.0, 1.0);
    float horizon = exp(-elevation * 5.0);
    float toward = pow(max(dot(rd, sun), 0.0), 8.0);
    vec3 top = mix(vec3(0.006, 0.013, 0.035), vec3(0.12, 0.29, 0.60), day);
    vec3 rim = mix(vec3(0.025, 0.035, 0.07), mix(vec3(0.52, 0.66, 0.83), vec3(1.05, 0.48, 0.19), gold), day);
    vec3 sky = mix(top, rim, horizon * 0.88);
    sky += directColour() * toward * (0.16 + gold * 0.48) * day;
    float disc = smoothstep(cos(0.024), cos(0.014), dot(rd, sun));
    sky += directColour() * disc * 12.0 * (1.0 - rainStrength * 0.8);
    float moon = smoothstep(cos(0.016), cos(0.010), dot(rd, -sun));
    sky += vec3(0.45, 0.55, 0.85) * moon * (1.0 - day);
    // A soft 2D cloud layer, not volumetric clouds. Same sky is used by reflections.
    if (rd.y > 0.025) {
        float t = max(70.0, 190.0 - cameraPosition.y) / max(rd.y, 0.025);
        vec2 uv = (cameraPosition.xz + rd.xz * t) * 0.0028 + vec2(frameTimeCounter * 0.003, 0.0);
        float cloud = smoothstep(0.48, 0.71, cloudNoise(uv));
        cloud *= smoothstep(0.025, 0.16, rd.y);
        float edge = clamp((cloudNoise(uv + sun.xz * 0.16) - cloudNoise(uv)) * 5.0 + 0.5, 0.0, 1.0);
        vec3 cloudLight = mix(vec3(0.018, 0.025, 0.05), mix(vec3(0.8), vec3(1.22, 0.67, 0.36), gold), day);
        sky = mix(sky, cloudLight * mix(0.6, 1.2, edge), cloud * 0.9);
    }
    sky = mix(sky, vec3(dot(sky, vec3(0.2126, 0.7152, 0.0722))) * 0.7, rainStrength * 0.6);
    return max(sky, vec3(0.0));
}
vec3 viewPosition(vec2 uv, float depth) {
    vec4 p = gbufferProjectionInverse * vec4(uv * 2.0 - 1.0, depth * 2.0 - 1.0, 1.0);
    return p.xyz / p.w;
}
vec3 viewRayWorld(vec2 uv) { return worldDirection(viewPosition(uv, 1.0)); }
#endif

#include "/lib/lighting.glsl"
uniform sampler2D texture;
uniform float alphaTestRef;
#ifdef MH_ENTITY
uniform vec4 entityColor;
#endif
varying vec2 vUV;
varying vec2 vLM;
varying vec4 vColour;
varying vec3 vPlayer;
varying vec3 vNormal;
#ifdef MH_TERRAIN
varying float vTerrainMaterial;
vec3 terrainDetailNormal(vec3 geometricNormal, vec3 textureColour, float material) {
    // Screen-space height derivatives: no adjacent atlas sprite is sampled.
    // Colour is not actual height data; keep the inference small and near-camera.
    float strength = 0.0;
    if (abs(material - 1003.0) < 0.5) strength = 1.0;
    if (abs(material - 1004.0) < 0.5) strength = 0.65;
    if (abs(material - 1006.0) < 0.5) strength = 0.45;
    float fade = 1.0 - smoothstep(16.0, 40.0, length(vPlayer));
    float height = dot(textureColour, vec3(0.2126, 0.7152, 0.0722));
    vec3 dx = dFdx(vPlayer), dy = dFdy(vPlayer);
    vec3 rx = cross(dy, geometricNormal), ry = cross(geometricNormal, dx);
    float determinant = dot(dx, rx);
    vec3 gradient = (rx * dFdx(height) + ry * dFdy(height)) * sign(determinant) / max(abs(determinant), 0.000001);
    gradient *= min(1.0, 2.0 / max(length(gradient), 0.00001));
    return normalize(geometricNormal - gradient * SURFACE_RELIEF * strength * fade);
}
#endif
void mhSurface() {
#ifdef MH_BASIC
    gl_FragData[0] = vec4(toLinear(vColour.rgb), vColour.a);
#else
    vec4 texel = texture2D(texture, vUV);
    float alpha = texel.a;
#ifndef MH_TERRAIN
    alpha *= vColour.a;
#endif
    vec3 albedo = toLinear(texel.rgb * vColour.rgb);
    vec3 n = length(vNormal) > 0.01 ? normalize(vNormal) : normalize(-vPlayer);
    float ao = 1.0;
#ifdef MH_TERRAIN
    ao = clamp(vColour.a, 0.0, 1.0);
#endif
    float shadows = 1.0;
#ifdef MH_PARTICLE
    shadows = 0.0;
#endif
#ifdef MH_TERRAIN
    vec3 detailNormal = terrainDetailNormal(n, texel.rgb, vTerrainMaterial);
#endif
    // Derivatives above must execute before potentially divergent cutout discard.
    if (alpha < alphaTestRef) discard;
#ifdef MH_TERRAIN
    vec3 lit = lightTerrainMaterial(albedo, n, detailNormal, vPlayer, vLM, ao, vTerrainMaterial);
#else
    vec3 lit = lightSurface(albedo, n, vPlayer, vLM, ao, shadows);
#endif
#ifdef MH_ENTITY
    lit = mix(lit, toLinear(entityColor.rgb), entityColor.a);
#endif
    gl_FragData[0] = vec4(lit, alpha);
#endif
}

uniform mat4 gbufferModelViewInverse;
varying vec2 vUV;
varying vec2 vLM;
varying vec4 vColour;
varying vec3 vPlayer;
varying vec3 vNormal;
#ifdef MH_TERRAIN
attribute vec4 mc_Entity;
varying float vTerrainMaterial;
#endif
void mhVertex() {
    gl_Position = ftransform();
    vUV = (gl_TextureMatrix[0] * gl_MultiTexCoord0).xy;
    vLM = (gl_TextureMatrix[1] * gl_MultiTexCoord1).xy;
    vColour = gl_Color;
    vec4 view = gl_ModelViewMatrix * gl_Vertex;
    vPlayer = (gbufferModelViewInverse * view).xyz;
    vec3 vn = gl_NormalMatrix * gl_Normal;
    vNormal = mat3(gbufferModelViewInverse) * vn;
#ifdef MH_TERRAIN
    vTerrainMaterial = mc_Entity.x;
#endif
}

#include "/lib/common.glsl"
uniform sampler2D shadowtex0;
uniform mat4 shadowModelView;
uniform mat4 shadowProjection;
// Unwarped shadow projection: precisely the same transform as shadow.vsh.
float shadowVisibility(vec3 playerPosition, vec3 normal, vec3 lightDirection) {
    vec4 sp = shadowProjection * shadowModelView * vec4(playerPosition + normal * 0.055, 1.0);
    vec3 uvz = sp.xyz / sp.w * 0.5 + 0.5;
    if (any(lessThan(uvz, vec3(0.002))) || any(greaterThan(uvz, vec3(0.998)))) return 1.0;
    float bias = 0.00030 + (1.0 - max(dot(normal, lightDirection), 0.0)) * 0.00065;
    float visibility = 0.0;
    for (int x = -1; x <= 1; ++x) for (int y = -1; y <= 1; ++y) {
        float depth = texture2D(shadowtex0, uvz.xy + vec2(float(x), float(y)) * (1.45 / 2048.0)).r;
        visibility += step(uvz.z - bias, depth);
    }
    float fade = smoothstep(65.0, 90.0, length(playerPosition.xz));
    return mix(visibility / 9.0, 1.0, fade);
}
vec3 lightSurface(vec3 albedo, vec3 normal, vec3 playerPosition, vec2 lm, float ao, float receiveShadow) {
    vec3 n = normalize(normal), lightDirection = worldDirection(shadowLightPosition);
    float day = daylight();
    float sky = clamp((lm.y - 0.03125) / 0.9375, 0.0, 1.0);
    float block = clamp((lm.x - 0.03125) / 0.9375, 0.0, 1.0);
    float diffuse = max(dot(n, lightDirection), 0.0);
    float visible = mix(1.0, shadowVisibility(playerPosition, n, lightDirection), receiveShadow);
    float hemisphere = mix(0.50, 1.0, n.y * 0.5 + 0.5);
    vec3 ambient = mix(vec3(0.045, 0.065, 0.12), vec3(0.42, 0.55, 0.76), day);
    ambient *= AMBIENT_STRENGTH * mix(0.06, 1.0, pow(sky, 1.5)) * hemisphere;
    vec3 direct = mix(vec3(0.22, 0.31, 0.52) * 0.22, directColour() * SUN_INTENSITY, day);
    direct *= diffuse * visible * smoothstep(0.65, 0.98, sky) * (1.0 - rainStrength * 0.85);
    vec3 torch = vec3(1.0, 0.48, 0.15) * pow(block, 3.0) * 3.1;
    return albedo * (ambient * mix(0.42, 1.0, ao) + direct * mix(0.78, 1.0, ao) + torch + vec3(0.012));
}

// Terrain-only extension: the approved water/other-surface lighting path above is unchanged.
vec2 terrainMaterialResponse(float material) {
    // Roughness and approximate metallic fraction.
    if (abs(material - 1003.0) < 0.5) return vec2(0.88, 0.0); // rough stone
    if (abs(material - 1004.0) < 0.5) return vec2(0.72, 0.0); // timber
    if (abs(material - 1005.0) < 0.5) return vec2(0.34, 0.9); // metal blocks
    if (abs(material - 1006.0) < 0.5) return vec2(0.98, 0.0); // soil/sand
    if (abs(material - 1007.0) < 0.5) return vec2(0.44, 0.0); // polished stone
    return vec2(0.94, 0.0);
}
vec3 terrainHighlight(vec3 albedo, vec3 normal, vec3 eye, vec3 light, float roughness, float metallic) {
    float nl = max(dot(normal, light), 0.0), nv = max(dot(normal, eye), 0.001);
    vec3 halfDirection = light + eye;
    if (length(halfDirection) < 0.0001) return vec3(0.0);
    vec3 h = normalize(halfDirection);
    float nh = max(dot(normal, h), 0.0), vh = max(dot(eye, h), 0.0);
    float a = roughness * roughness, a2 = a * a;
    float denominator = nh * nh * (a2 - 1.0) + 1.0;
    float distribution = a2 / max(MH_PI * denominator * denominator, 0.0001);
    float k = (roughness + 1.0) * (roughness + 1.0) / 8.0;
    float geometry = (nl / max(nl * (1.0 - k) + k, 0.001)) * (nv / (nv * (1.0 - k) + k));
    vec3 f0 = mix(vec3(0.04), clamp(albedo * 2.5, vec3(0.25), vec3(0.95)), metallic);
    vec3 fresnel = f0 + (1.0 - f0) * pow(1.0 - vh, 5.0);
    return min(distribution * geometry * fresnel / max(4.0 * nv, 0.001), vec3(2.5));
}
vec3 lightTerrainMaterial(vec3 albedo, vec3 geometricNormal, vec3 detailNormal, vec3 playerPosition, vec2 lm, float ao, float material) {
    vec2 response = terrainMaterialResponse(material);
    vec3 diffuseAlbedo = albedo * (1.0 - response.y * 0.55);
    vec3 colour = lightSurface(diffuseAlbedo, geometricNormal, playerPosition, lm, ao, 1.0);
    vec3 light = worldDirection(shadowLightPosition);
    vec3 toEye = gbufferModelViewInverse[3].xyz - playerPosition;
    vec3 eye = toEye / max(length(toEye), 0.0001);
    // Geometric normal, not inferred detail, controls shadow lookup/bias.
    float visibility = shadowVisibility(playerPosition, geometricNormal, light);
    float sky = clamp((lm.y - 0.03125) / 0.9375, 0.0, 1.0);
    vec3 incident = mix(vec3(0.22, 0.31, 0.52) * 0.22, directColour() * SUN_INTENSITY, daylight());
    incident *= visibility * smoothstep(0.65, 0.98, sky) * (1.0 - rainStrength * 0.85);
    float diffuseChange = max(dot(detailNormal, light), 0.0) - max(dot(geometricNormal, light), 0.0);
    colour += diffuseAlbedo * incident * diffuseChange * mix(0.78, 1.0, ao);
    colour += terrainHighlight(albedo, detailNormal, eye, light, response.x, response.y) * incident * MATERIAL_HIGHLIGHTS;
    return max(colour, vec3(0.0));
}

